        playPauseBtn = makeIconButton(iconPlay(), "Play / Pause", togglePlayPause);
        shuffleBtn = makeIconButton(makeShuffleIcon(), "Shuffle (toggle)", toggleShuffle);
        repeatBtn = makeIconButton(makeRepeatIcon(false), "Repeat", cycleRepeat);

